// Isolation test (OS-12) — construct CurrencyOrder with its declared inputs and nothing
// else, then exercise every public operation. Run with the environment cleared: anything
// this class reaches for outside its inputs fails here. (Generated by new-object.py,
// rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { CurrencyOrder } from "../src/catalog/index.js";

describe("CurrencyOrder in isolation", () => {
  // Two orders over the same three currencies, differing ONLY in their order.
  const a = () => new CurrencyOrder({ currencies: ["p", "q", "r"] });
  const b = () => new CurrencyOrder({ currencies: ["q", "p", "r"] });

  it("refuses to construct when an input is missing", () => {
    expect(() => new CurrencyOrder({} as never)).toThrow();
  });

  it("currencies answers differently when currencies differs", () => {
    expect(a().currencies()).not.toEqual(b().currencies());
  });

  it("least answers differently when currencies differs", () => {
    expect(a().least()).not.toEqual(b().least());
  });

  it("predecessors answers differently when currencies differs", () => {
    const lastOf = (o: CurrencyOrder) => o.currencies().find((c) => c === "q")!;
    expect(a().predecessors(lastOf(a()))).not.toEqual(b().predecessors(lastOf(b())));
  });
});
